// Telegram rechaza Markdown desbalanceado. Limpiamos formato y escapamos HTML para parse_mode HTML.
const raw = $json.output || $json.text || '';
let texto = String(raw)
  .replace(/```[a-z]*\n?/gi, '')
  .replace(/```/g, '')
  .replace(/[*`~#>\[\]]/g, '')
  .trim();
// Escapar caracteres especiales de HTML
texto = texto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { texto: texto || 'No pude generar una respuesta, intenta de nuevo.' } }];

// Validacion antes de notificar: sin id_estudiante el envio falla,
// y solo interesan las tutorias vigentes.
return $input.all().map(i => i.json)
  .filter(t => t.id_tutoria && t.id_estudiante && ['Asignada', 'Confirmada'].includes(t.estado))
  .map(t => ({ json: t }));

const hoy = $now.startOf('day');
const desde = hoy.minus({ days: 7 }).toFormat('yyyy-MM-dd');
const hasta = hoy.plus({ days: 7 }).toFormat('yyyy-MM-dd');

const rows = $input.all().map(i => i.json)
  .filter(t => t.id_tutoria && String(t.fecha) >= desde && String(t.fecha) <= hasta);

const cuenta = (campo) => rows.reduce((acc, t) => {
  const k = t[campo] || 'sin_dato';
  acc[k] = (acc[k] || 0) + 1;
  return acc;
}, {});

return [{ json: {
  generado_en: $now.toISO(),
  periodo: { desde, hasta },
  total: rows.length,
  por_estado: cuenta('estado'),
  por_materia: cuenta('materia'),
  por_tutor: cuenta('id_tutor'),
  tutorias: rows.map(t => ({
    id_tutoria: t.id_tutoria, id_tutor: t.id_tutor, materia: t.materia,
    fecha: t.fecha, hora: t.hora, estado: t.estado
  }))
} }];

// Cierra tutorias cuya fecha y hora ya pasaron usando la zona horaria de la instancia.
const ahora = $now.toJSDate();
return $input.all().map(i => i.json)
  .filter(t => {
    if (!t.id_tutoria || !t.fecha || !t.hora) return false;
    const fechaHora = new Date(t.fecha + 'T' + t.hora);
    return fechaHora < ahora && ['Asignada', 'Confirmada'].includes(t.estado);
  })
  .map(t => ({ json: { id_tutoria: t.id_tutoria } }));

// Texto plano: el resumen lo escribe la IA y no controlamos si mete
// asteriscos, asi que nada de Markdown (Telegram devuelve 400).
const r = $('Calcular Reporte').first().json;
const linea = (obj) => Object.entries(obj).map(([k, v]) => `  ${k}: ${v}`).join('\n') || '  (sin datos)';
const resumen = String($json.text || '').replace(/[*`~#>\[\]]/g, '').trim();

let texto = [
  'REPORTE SEMANAL DE TUTORIAS',
  `Periodo: ${r.periodo.desde} a ${r.periodo.hasta}`,
  `Total: ${r.total}`,
  '',
  'Por estado:', linea(r.por_estado),
  '',
  'Por materia:', linea(r.por_materia),
  '',
  'Por tutor:', linea(r.por_tutor),
  '',
  'Resumen:', resumen || '(sin resumen)'
].join('\n');

// Escapar caracteres especiales de HTML para parse_mode HTML
texto = texto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [{ json: { texto } }];
